"""Regenerate docs/ENV_VARS.md from app.config.ENV_VARS (names only, never values)."""
from __future__ import annotations

import pathlib
import sys

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1]))
from app.config import ENV_VARS, SECRET_VARS  # noqa: E402

lines = [
    "# Environment variables",
    "",
    "Generated by `scripts/gen_env_docs.py` from `app/config.py`; `tests/test_contracts_research_config.py` fails if",
    "this file falls behind. Names only. Secrets are injected at runtime (Render secret env vars with `sync: false`),",
    "never committed, never logged. `prod` = required in staging and production; `worker` = worker service only.",
    "",
    "| Name | Secret | Required | Purpose |",
    "| --- | --- | --- | --- |",
]
for name, (purpose, required) in ENV_VARS.items():
    lines.append(f"| `{name}` | {'yes' if name in SECRET_VARS else ''} | {required} | {purpose.replace('|', '/')} |")
pathlib.Path(__file__).resolve().parents[1].joinpath("docs", "ENV_VARS.md").write_text("\n".join(lines) + "\n")
print(f"wrote {len(ENV_VARS)} variables")
